import{_ as a,o as e,c as o,a5 as d}from"./chunks/framework.B5tqjWbr.js";const m=JSON.parse('{"title":"示例 5：参数辨识流程观察","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"simulation","chapterTitle":"仿真与调试","chapterOrder":10,"category":"仿真与调试","source":"motor","visibility":"public","title":"示例 5：参数辨识流程观察","tags":["motor-control"],"status":"learning","summary":"观察参数自整定（Commissioning）的分步辨识过程：电阻→电感→磁链→惯量。","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/simulation/code-examples/05-commissioning-debug/README.md","filePath":"content/motor/simulation/code-examples/05-commissioning-debug/README.md","lastUpdated":1783096495000}'),s={name:"content/motor/simulation/code-examples/05-commissioning-debug/README.md"};function i(n,t,l,r,c,p){return e(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="示例-5-参数辨识流程观察" tabindex="-1">示例 5：参数辨识流程观察 <a class="header-anchor" href="#示例-5-参数辨识流程观察" aria-label="Permalink to &quot;示例 5：参数辨识流程观察&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>观察参数自整定（Commissioning）的分步辨识过程：电阻→电感→磁链→惯量。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>在 Streamlit sidebar 中将 <code>user.mode_select_synchronous_motor</code> 设为 9</li><li>点击「Save to C and compile」</li><li>观察控制台输出和仿真波形</li></ol><h2 id="辨识流程" tabindex="-1">辨识流程 <a class="header-anchor" href="#辨识流程" aria-label="Permalink to &quot;辨识流程&quot;">​</a></h2><p>参数自整定按以下顺序自动执行（<code>bool_comm_status</code> 状态机）：</p><div class="kb-table-scroll"><table><thead><tr><th>状态</th><th>辨识内容</th><th>方法</th><th>控制台输出关键词</th></tr></thead><tbody><tr><td>1</td><td>定子电阻 R</td><td>稳态 I-V 法 + 最小二乘拟合</td><td><code>R=xxx Ohm</code></td></tr><tr><td>2</td><td>电感 L（阶跃法）</td><td>施加电压阶跃，测电流斜率</td><td><code>L=xxx</code></td></tr><tr><td>3</td><td>电感 L（正弦法）</td><td>正弦激励 + 相干解调</td><td><code>L3=xxx</code></td></tr><tr><td>4</td><td>永磁体磁链 KE</td><td>反电动势法（速度闭环）</td><td><code>COMM.KE=xxx</code></td></tr><tr><td>5</td><td>转动惯量 Js</td><td>Awaya1992 观测器</td><td><code>Js=xxx</code></td></tr></tbody></table></div><h2 id="预期输出" tabindex="-1">预期输出 <a class="header-anchor" href="#预期输出" aria-label="Permalink to &quot;预期输出&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>R=0.475 Ohm, inverter_voltage_drop=0.5</span></span>
<span class="line"><span>L=2.05e-3, ...</span></span>
<span class="line"><span>L3=2.05e-3, ...</span></span>
<span class="line"><span>COMM.KE=0.01072 | ACM.KE=0.01072</span></span>
<span class="line"><span>Js=3.5e-6</span></span></code></pre></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>辨识时电机不能转动（除步骤 4/5 外）</li><li>步骤 4 需要电机能自由旋转</li><li>如果辨识值偏差大，检查电机参数初始值和 PI 参数</li><li>可以通过修改 <code>COMM.bool_comm_status</code> 的初始值跳过某步</li></ul>`,12)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
